16	package org.springframework.samples.petclinic.model;
17	
18	import org.springframework.core.style.ToStringCreator;
19	
20	import jakarta.persistence.*;
21	import jakarta.validation.constraints.Digits;
22	import jakarta.validation.constraints.Email;
23	import jakarta.validation.constraints.NotEmpty;
24	import jakarta.validation.constraints.Pattern;
25	
26	import java.util.*;
27	
28	/**
29	 * Simple JavaBean domain object representing an owner.
30	 *
31	 * @author Ken Krebs
32	 * @author Juergen Hoeller
33	 * @author Sam Brannen
34	 * @author Michael Isvy
35	 */
36	@Entity
37	@Table(name = "owners")
38	public class Owner extends Person {
39	    @Column(name = "address")
40	    @NotEmpty
41	    private String address;
42	
43	    @Column(name = "city")
44	    @NotEmpty
45	    private String city;
46	
47	    @Column(name = "telephone")
48	    @NotEmpty
49	    @Digits(fraction = 0, integer = 10)
50	    @Pattern(regexp = "^[0-9]{10}$", message = "Phone number must be exactly 10 digits")
51	    private String telephone;
52	
53	    @Column(name = "email")
54	    @Email
55	    private String email;
56	
57	    @OneToMany(cascade = CascadeType.ALL, mappedBy = "owner", fetch = FetchType.EAGER)
58	    private Set<Pet> pets;
59	
60	    public String getAddress() {
61	        return this.address;
62	    }
63	
64	    public void setAddress(String address) {
65	        this.address = address;
66	    }
67	
68	    public String getCity() {
69	        return this.city;
70	    }
71	
72	    public void setCity(String city) {
73	        this.city = city;
74	    }
75	
76	    public String getTelephone() {
77	        return this.telephone;
78	    }
79	
80	    public void setTelephone(String telephone) {
81	        this.telephone = telephone;
82	    }
83	
84	    public String getEmail() {
85	        return this.email;
86	    }
87	
88	    /**
89	     * Stores the email lower-cased so the value is persisted and returned in a canonical
90	     * form. {@code null} is preserved because the email is optional.
91	     */
92	    public void setEmail(String email) {
93	        this.email = (email == null) ? null : email.toLowerCase(Locale.ROOT);
94	    }
95	
96	    protected Set<Pet> getPetsInternal() {
97	        if (this.pets == null) {
98	            this.pets = new HashSet<>();
99	        }
100	        return this.pets;
101	    }
102	
103	    protected void setPetsInternal(Set<Pet> pets) {
104	        this.pets = pets;
105	    }
106	
107	    public List<Pet> getPets() {
108	        List<Pet> sortedPets = new ArrayList<>(getPetsInternal());
109	        sortedPets.sort(Comparator.comparing(Pet::getName, String.CASE_INSENSITIVE_ORDER));
110	        return Collections.unmodifiableList(sortedPets);
111	    }
112	
113	    public void setPets(List<Pet> pets) {
114	        this.pets = new HashSet<>(pets);
115	    }
116	
117	    public void addPet(Pet pet) {
118	        getPetsInternal().add(pet);
119	        pet.setOwner(this);
120	    }
121	
122	    /**
123	     * Return the Pet with the given name, or null if none found for this Owner.
124	     *
125	     * @param name to test
126	     * @return true if pet name is already in use
127	     */
128	    public Pet getPet(String name) {
129	        return getPet(name, false);
130	    }
131	
132	    /**
133	     * Return the Pet with the given name, or null if none found for this Owner.
134	     *
135	     * @param name to test
136	     * @return true if pet name is already in use
137	     */
138	    public Pet getPet(String name, boolean ignoreNew) {
139	        name = name.toLowerCase();
140	        for (Pet pet : getPetsInternal()) {
141	            if (!ignoreNew || !pet.isNew()) {
142	                String compName = pet.getName();
143	                compName = compName.toLowerCase();
144	                if (compName.equals(name)) {
145	                    return pet;
146	                }
147	            }
148	        }
149	        return null;
150	    }
151	
152	    public Pet getPet(Integer petId) {
153	        return getPetsInternal().stream().filter(p -> p.getId().equals(petId)).findFirst().orElse(null);
154	    }
155	
156	    @Override
157	    public String toString() {
158	        return new ToStringCreator(this)
159	
160	            .append("id", this.getId())
161	            .append("new", this.isNew())
162	            .append("lastName", this.getLastName())
163	            .append("firstName", this.getFirstName())
164	            .append("address", this.address)
165	            .append("city", this.city)
166	            .append("telephone", this.telephone)
167	            .toString();
168	    }
169	}
